require_once __DIR__.'/../includes/auth.php';auth_require();require_once __DIR__.'/../includes/listing.php';$error='';$purchase=(int)($_GET['purchase_id']??$_POST['purchase_id']??0);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 $quantities=$_POST['quantities']??null;if(!is_array($quantities)||!$quantities)throw new InvalidArgumentException(__t('Enter the quantities to return.','مقدار اجناس برگشتی را بنویسید.','د ستنولو مقدار ولیکئ.'));
 purchase_return_post($purchase,(string)($_POST['reason']??''),$quantities,(string)($_POST['request_key']??''));redirect(BASE_URL.'modules/purchase_returns.php');
}catch(Throwable $e){http_response_code(in_array($e->getCode(),[403,429],true)?$e->getCode():422);$error=public_error($e);}
$source=null;$items=[];if($purchase){$q=$pdo->prepare('SELECT * FROM inventory_purchases WHERE id=? AND shop_id=?');$q->execute([$purchase,shop_id()]);$source=$q->fetch();if(!$source)access_deny(404,'not_found',__t('Purchase unavailable.','خرید یافت نشد.','پېرود ونه موندل شو.'));$q=$pdo->prepare('SELECT i.*,(SELECT COALESCE(SUM(r.quantity),0) FROM purchase_return_lines r WHERE r.purchase_item_id=i.id AND r.shop_id=i.shop_id) AS returned_qty FROM inventory_purchase_items i WHERE i.purchase_id=? AND i.shop_id=? ORDER BY i.id');$q->execute([$purchase,shop_id()]);$items=$q->fetchAll();}
$sorts=['newest'=>['r.id DESC','Newest first','تازه‌ترین اول'],'oldest'=>['r.id ASC','Oldest first','قدیمی‌ترین اول']];[$list,$history]=listing_query($pdo,'SELECT r.*,p.reference FROM purchase_returns r JOIN inventory_purchases p ON p.id=r.purchase_id AND p.shop_id=r.shop_id WHERE r.shop_id=?',[shop_id()],$sorts);$pageTitle=__t('Purchase returns','برگشت خرید','د پېرود ستنول');require __DIR__.'/../includes/header.php';?>
<h1><?= sanitize($pageTitle) ?></h1><p><?= __t('Return all or part of a purchase. The unpaid balance is reduced first; any paid portion becomes a supplier refund receivable. Record actual money received separately in Cash & bank. Reserved or unavailable goods cannot be returned.','خرید را کامل یا قسمتی برگشت دهید. نخست بدهی باقی‌مانده کم می‌شود؛ بخش پرداخت‌شده به طلب از عرضه‌کننده تبدیل می‌شود. پول واقعی را جدا در صندوق و بانک دریافت کنید. جنس رزرف‌شده یا ناموجود برگشت نمی‌شود.','پېرود بشپړ یا برخه ستنول؛ پاتې پور لومړی کمېږي او پیسې جلا ترلاسه کېږي.') ?></p>
<?php if($error):?><p class="alert alert-danger" role="alert"><?= sanitize($error) ?></p><?php endif ?>
<section class="card modern-form"><form method="get"><label><?= __t('Purchase invoice','بل خرید','د پېرود بل') ?><select class="form-control" name="purchase_id" required><option value=""><?= __t('Choose a purchase','خرید را انتخاب کنید','پېرود وټاکئ') ?></option><?php $q=$pdo->prepare('SELECT p.id,p.reference,p.total_amount,p.currency_code FROM inventory_purchases p WHERE p.shop_id=? AND NOT EXISTS(SELECT 1 FROM purchase_returns r WHERE r.purchase_id=p.id AND r.shop_id=p.shop_id AND r.full_return=1) ORDER BY p.id DESC LIMIT 250');$q->execute([shop_id()]);foreach($q->fetchAll() as $p):?><option value="<?= (int)$p['id'] ?>" <?= $purchase===(int)$p['id']?'selected':'' ?>><?= sanitize($p['reference'].' · '.$p['total_amount'].' '.$p['currency_code']) ?></option><?php endforeach ?></select></label><button class="btn btn-primary"><?= __t('Open purchase','بازکردن خرید','پېرود پرانیزئ') ?></button></form></section>
<?php if($source):$balance=purchase_balance($source);?><section class="card modern-form"><h2><?= sanitize($source['reference']) ?></h2><p><?= __t('Payable','بدهی','پور') ?>: <?= sanitize($balance['payable'].' '.$source['currency_code']) ?> · <?= __t('Refund due','طلب برگشت پول','د ستنولو طلب') ?>: <?= sanitize($balance['refund_due'].' '.$source['currency_code']) ?></p><form method="post"><?= csrf_field() ?><input name="action" type="hidden" value="approve_return"><input name="purchase_id" type="hidden" value="<?= $purchase ?>"><input name="request_key" type="hidden" value="<?= bin2hex(random_bytes(16)) ?>"><div class="form-grid"><?php foreach($items as $item):$left=dec_sub($item['quantity'],$item['returned_qty'],3);?><label><?= sanitize($item['product_name'].' · '.__t('Remaining to return','باقی‌ماندهٔ قابل برگشت','د ستنولو پاتې').': '.$left.' '.$item['unit']) ?><input class="form-control" name="quantities[<?= (int)$item['id'] ?>]" type="number" min="0" max="<?= sanitize($left) ?>" step="0.001" value="0" required></label><?php endforeach ?></div><label><?= __t('Return reason','دلیل برگشت','د ستنولو لامل') ?><textarea class="form-control" name="reason" minlength="3" maxlength="500" required></textarea></label><button class="btn btn-primary"><?= __t('Approve purchase return','تأیید برگشت خرید','د پېرود ستنول تایید') ?></button></form></section><?php endif ?>
<section class="card modern-form table-responsive"><h2><?= __t('Return history','تاریخچهٔ برگشت','د ستنولو تاریخ') ?></h2><table class="table"><thead><tr><?php foreach([__t('Reference','مرجع','شمېره'),__t('Date','تاریخ','نېټه'),__t('Returned value','مبلغ برگشت','د ستنولو ارزښت'),__t('Status','وضعیت','حالت')] as $label):?><th><?= $label ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($history as $row):?><tr><td><a href="?purchase_id=<?= (int)$row['purchase_id'] ?>"><?= sanitize($row['reference']) ?></a></td><td><?= sanitize($row['created_at']) ?></td><td><?= sanitize($row['total_amount'].' '.$row['currency_code']) ?></td><td><?= $row['full_return']?__t('Fully returned','کامل برگشت‌شده','بشپړ ستنول شوی'):__t('Partially returned','قسمتی برگشت‌شده','برخه ستنول شوې') ?></td></tr><?php endforeach ?></tbody></table></section>
<?php listing_controls_form($list);listing_footer($list);require __DIR__.'/../includes/footer.php'; ?>
